string canPartition(int nums[], int n) {
    int sum = 0;
    for(int i=0;i<n;i++) sum+=nums[i];
    if(sum%2) return "false";
    int target = sum/2;
    bool dp[target+1];
    memset(dp, false, sizeof(dp));
    dp[0] = true;
    for(int i=0;i<n;i++)
        for(int j=target;j>=nums[i];j--)
            dp[j] = dp[j] || dp[j-nums[i]];
    return dp[target] ? "true" : "false";
}

